def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                    hydration_hooks=None, **handlers):
    """Appends a DISCARD message to the output queue."""
    # Check if n is a valid number
    if not isinstance(n, int) or n < -1:
        raise ValueError("Invalid value for n")

    # Check if qid is a valid query ID
    if not isinstance(qid, int) or qid < -1:
        raise ValueError("Invalid value for qid")

    # Check if dehydration_hooks is a dict
    if not isinstance(dehydration_hooks, dict):
        raise ValueError("dehydration_hooks must be a dict")

    # Check if hydration_hooks is a dict
    if not isinstance(hydration_hooks, dict):
        raise ValueError("hydration_hooks must be a dict")

    # Create a DISCARD message
    message = {
        "DATA": {
            "query_id": qid,
            "n": n
        }
    }

    # Dehydrate types
    for (key, value) in dehydration_hooks.items():
        message[key] = value(message[key])

    # Add hydration hooks
    message["_hydration_hooks"] = hydration_hooks

    # Append message to output queue
    self.add_output(message, **handlers)

    return self

