def minimalBases(classes):
    # Sort the classes in ascending order
    classes.sort()

    # Initialize a result list to store the minimal base classes
    minimal_bases = []

    # Iterate over the sorted classes
    for class_ in classes:
        # Check if the current class is already in the result list
        if class_ not in minimal_bases:
            # Add the current class to the result list
            minimal_bases.append(class_)

            # Iterate over the remaining classes
            for next_class in classes[classes.index(class_)+1:]:
                # Check if the current class is a base class of the next class
                if class_ in next_class.__bases__:
                    # Add the next class to the result list if it is not already in
                    if next_class not in minimal_bases:
                        minimal_bases.append(next_class)

    return minimal_bases

