def validate_observer_schema(schemas):
    """
    Validate the observer schemas in the given dictionary.

    Args:
        schemas (dict): A dictionary mapping resource types to observer schemas

    Raises:
        krake.data.observer.InvalidSchema: If any of the observer schemas are invalid
            for the specified resource types
    """
    for resource_type, schema in schemas.items():
        # Check if the resource type is valid
        if resource_type not in RESOURCE_TYPES:
            raise InvalidResourceType(f"Invalid resource type '{resource_type}'")

        # Check if the schema is a dictionary
        if not isinstance(schema, dict):
            raise InvalidSchema(f"Invalid observer schema for resource type '{resource_type}'")

        # Check if the schema has the required fields
        required_fields = OBSERVER_SCHEMA[resource_type]
        for required_field in required_fields:
            if required_field not in schema:
                raise MissingRequiredField(f"Missing required field '{required_field}' in observer schema for resource type '{resource_type}'")

        # Check if the schema has the correct data types
        for field, field_type in schema.items():
            if not isinstance(field_type, type):
                raise InvalidFieldType(f"Invalid field type for field '{field}' in observer schema for resource type '{resource_type}'. Expected '{OBSERVER_SCHEMA[resource_type][field]}, but got '{type(field_type)}'")

