def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of the in-style parameters.

    :param sql: The SQL query.
    :type sql: str or bytes
    :param params: The set of in-style parameters.
    :type params: dict or list
    :return: A tuple containing the formatted SQL query and the set of converted out-style parameters.
    :rtype: tuple
    """

    # Validate inputs
    if not isinstance(sql, (str, bytes)):
        raise TypeError("'sql' must be a str or bytes")
    if not isinstance(params, (Mapping, Sequence)):
        raise TypeError("'params' must be a Mapping or Sequence")

    # Convert in-style parameters to out-style parameters
    out_params = {}
    if isinstance(params, Mapping):
        for key, value in params.items():
            if not isinstance(key, (str, int)):
                raise TypeError(f"'params' keys must be str or int, not {type(key)}")
            out_params[key] = value
    elif isinstance(params, Sequence):
        for i, value in enumerate(params):
            out_params[i + 1] = value

    # Replace in-style parameters with out-style parameters in the SQL query
    if isinstance(sql, str):
        for param in iterkeys(params):
            sql = sql.replace("?" + str(param), ":%s" % param)
    else:
        for param in iterkeys(params):
            sql = sql.replace(bytes([1]), b"%s".encode())

    return (sql, out_params)

def format(sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
    :class:`list`).
    """

    # Step 1: Check if the parameters are properly formatted
    if not isinstance(params, (dict, list)):
        raise TypeError("'params' must be a dictionary or a list")

    if isinstance(params, dict):
        if not all(isinstance(key, (str, int)) for key in params.keys()):
            raise TypeError("'params' keys must be strings or integers")

    if isinstance(params, dict):
        if not all(isinstance(value, (str, int)) for value in params.values()):
            raise TypeError("'params' values must be strings or integers")

    # Step 2: Convert the in-style parameters to out-style parameters
    if isinstance(params, dict):
        params = {"{" + key + "}": value for key, value in params.items()}

    if isinstance(params, list):
        params = [":p" + str(index + 1) for index, value in enumerate(params)]

    # Step 3: Replace the in-style parameters in the SQL query
    for parameter in params:
        sql = sql.replace(parameter, "", 1)

    return (sql, params)

def formatmany(sql, many_params):
    # Step 1: Check for valid inputs
    if not sql:
        raise ValueError("SQL query cannot be empty")
    if not many_params:
        raise ValueError("At least one set of in-style parameters must be provided")

    # Step 2: Convert multiple sets of in-style parameters to out-style parameters
    out_params = []
    for params in many_params:
        if isinstance(params, dict):
            out_params.append(dict(zip(params.keys(), params.values())))
        elif isinstance(params, (list, tuple)):
            out_params.append(list(zip(params)))
        else:
            raise ValueError("In-style parameters must be a dict or a list")

    # Step 3: Convert SQL query to use out-style parameters
    sql = sql.replace(SQLParams.in_style, SQLParams.out_style)

    # Step 4: Return formatted SQL query and converted out-style parameters
    return sql, out_params

