    try:
        digest_filepath = self.path / ".digests" / "ocfl_1.0.json"
        with open(digest_filepath) as f:
            digests = json.load(f)
        for digest in digests:
            digest_filepath = self.path / digest
            if not digest_filepath.is_file():
                raise ValueError(f"{digest_filepath} not found")
            with open(digest_filepath) as f:
                data = json.load(f)
                if "checksum" not in data or "size" not in data or "mimetype" not in data:
                    raise ValueError(f"{digest_filepath} does not have the required keys")
                if data["mimetype"] not in ["application/json", "text/plain"]:
                    raise ValueError(f"{digest_filepath} has an invalid mimetype")
                actual_size = os.path.getsize(digest_filepath)
                if actual_size != int(data["size"]):
                    raise ValueError(f"{digest_filepath} has a size mismatch")
                expected_digest = data["checksum"].encode("utf-8")
                actual_digest = pyfs.utils.hashlib.sha256(digest_filepath, data["mimetype"]).hexdigest()
                if actual_digest != expected_digest:
                    raise ValueError(f"{digest_filepath} has a digest mismatch")
    except (ValueError, OSError) as e:
        print(f"Validation failed: {e}")
        return False
    return True

