                spec_version = "0.0.1"
            elif type_value == "type: cloud" or type_value == "Type: Cloud":
                spec_version = "0.0.2"
            else:
                raise ValueError("Invalid type value: {type_value}")
        else:
            spec_version = self.spec_version

    if spec_version is None:
        raise ValueError("Unknown specification version")

    version_parts = spec_version.split(".")
    if len(version_parts) != 3:
        raise ValueError("Invalid specification version: {spec_version}")

    major, minor, patch = version_parts
    if not major.isdigit() or not minor.isdigit() or not patch.isdigit():
        raise ValueError("Invalid specification version: {spec_version}")

    major = int(major)
    minor = int(minor)
    patch = int(patch)

    if major < 0 or minor < 0 or patch < 0:
        raise ValueError("Invalid specification version: {spec_version}")

    if major > 1 or minor > 0 or patch > 0:
        raise ValueError("Invalid specification version: {spec_version}")

    return spec_version

