        if i % 2 == 0:
            # Absorption
            if arg in result:
                result[i] = args[i]
            else:
                result.append(args[i])
        else:
            # Negative absorption
            if arg in result:
                result[i] = args[i-1] & args[i]
            else:
                result.append(args[i-1] & args[i])
