    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    # Initialize an empty dict to store the parsed arguments
    parsed_arguments = {}

    # Iterate through the unparsed arguments and parse each one
    for arg in unparsed_arguments:
