    # Create a new instance of the argparse namespace
    namespace = argparse.Namespace()

    # Iterate through the unparsed arguments and populate the namespace with options
    for arg in unparsed_arguments:
        # Check if the argument is relevant to the current subparser
        if arg.startswith(f'--{subparser_name}') or arg.startswith(f'--{subparser_name}-'):
            # If it is, parse the argument and add it to the namespace
            namespace.__dict__[arg.split('--')[1]] = parse_argument(arg)

