def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_subparsers = {}
    unclaimed_arguments = []
    for arg in unparsed_arguments:
        for name, parser in subparsers.items():
            try:
                namespace = parser.parse_args([arg])
                parsed_subparsers[name] = namespace
                break
            except SystemExit:
                pass
        else:
            unclaimed_arguments.append(arg)
    return parsed_subparsers, unclaimed_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    subparser_names = subparsers.keys()
    parsed_arguments = {}
    remaining_arguments = []

    for argument in unparsed_arguments:
        for subparser_name in subparser_names:
            subparser = subparsers[subparser_name]
            if argument in subparser._option_string_actions:
                action = subparser._option_string_actions[argument]
                if action.option_string == argument:
                    if action.dest not in parsed_arguments:
                        parsed_arguments[action.dest] = []
                    parsed_arguments[action.dest].append(action)
                    break
            elif argument in subparser._defaults:
                default_action = subparser._defaults[argument]
                if default_action.dest not in parsed_arguments:
                    parsed_arguments[default_action.dest] = []
                parsed_arguments[default_action.dest].append(default_action)
                break
        else:
            remaining_arguments.append(argument)
    return parsed_arguments, remaining_arguments

