    if not isinstance(number, int) or not isinstance(alphabet, list) or not all(isinstance(c, str) for c in alphabet):
        raise TypeError("inputs must be of type int, list[str], and list[str]")
    if padding is not None and not isinstance(padding, int):
        raise TypeError("padding must be of type int")

    result = ""
