def split(s, platform='this'):
    if platform == 'this':
        platform = 1 if sys.platform == 'linux' or sys.platform == 'darwin' else 0
    if platform == 1:
        # On POSIX platforms, use shlex.split()
        import shlex
        return shlex.split(s)
    elif platform == 0:
        # On Windows/CMD platforms, use a custom splitter
        import re
        output = []
        pos = 0
        in_quote = False
        current = ''
        for match in re.finditer(r'\"{0,2}', s):
            # Add the current substring to the output list
            # if it's not empty and we're not in quotes
            if current and not in_quote:
                output.append(current)
            # Add the quote character to the output list if we're in quotes
            if match.group() == '\"':
                in_quote = not in_quote
            current = ''
            # Skip the quote character if we're in quotes
            pos += 1 if in_quote else 2
        # Add the last substring to the output list if it's not empty
        if current and not in_quote:
            output.append(current)
        return output

def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp"):

    if not os.path.exists(archive_path):
        raise ValueError(f"Invalid archive_path: {archive_path} does not exist.")

    if filename is None:
        filename = os.path.basename(archive_path)

    archiver = None
    if filename.lower().endswith(".zip"):
        archiver = "unzip"
    elif filename.lower().endswith(".tar.gz"):
        archiver = "tar"
    else:
        raise ValueError(f"Invalid archive type: {filename} is not a valid archive format.")

    with tempfile.TemporaryDirectory(dir=tmp_path) as tmp_dir:
        output_path = os.path.join(tmp_dir, "output")
        command = f"{archiver} x {archive_path} -d {output_path}"
        process = subprocess.run(command, shell=True, stdout=subprocess.PIPE)
        if process.returncode != 0:
            raise RuntimeError(f"Failed to extract archive: {process.stderr.decode().strip()}")
        repo_url = f"file://{output_path}"
        return repo_url

