    # Check if the time zone offset is UTC
    if zone_str == "Z":
        return dt.replace(tzinfo=tzutc())

    # Check if the time zone offset is an ISO-8601 weekday
    if len(zone_str) == 5 and zone_str[:3] == "ISO":
        return dt.replace(tzinfo=tzoffset(zone_str[3:], None))

    # Check if the time zone offset is an ISO-8601 weekday and day
    if len(zone_str) == 9 and zone_str[:6] == "ISO-W":
        week, day = int(zone_str[6:8]), int(zone_str[8])
        return dt.replace(tzinfo=tzoffset(f"ISO-W{week}-{day}", None))

    # Check if the time zone offset is an ISO-8601 week
    if len(zone_str) == 7 and zone_str[:3] == "ISO":
        week = int(zone_str[3:])
        return dt.replace(tzinfo=tzoffset(f"ISO-W{week}", None))

    # Check if the time zone offset is an ISO-8601 day
    if len(zone_str) == 4:
        # Check if the day is 7-digit and a weekday
        try:
