                if i + 1 < len(text) and text[i + 1].isalpha():
                    # Add the tag to the set of tags
                    tags.add(text[i + 1:i + 1])

    # If a replacer function was passed, use it to replace the tags in the text
    if replacer:
        for tag in tags:
